import { memo } from "react";
import { NotFoundLayout, type NotFoundProps } from "./not-found.shared";

export type { NotFoundProps } from "./not-found.shared";

export const NotFound = memo(function NotFound(props: NotFoundProps = {}) {
  return <NotFoundLayout {...props} layout="centered" />;
});

import { memo, type ComponentProps } from "react";
import { Button } from "../components/button";

export type NotFoundProps = ComponentProps<"section"> & {
  title?: string;
  description?: string;
  homeHref?: string;
  homeLabel?: string;
  secondaryHref?: string;
  secondaryLabel?: string;
};

export const NotFoundLayout = memo(function NotFoundLayout({
  title = "This page took a wrong turn.",
  description = "The page you’re looking for may have moved, or the link might be a little off. Let’s get you somewhere familiar.",
  homeHref = "/",
  homeLabel = "Back to home",
  secondaryHref,
  secondaryLabel = "Contact support",
  className = "",
  layout = "centered",
  ...props
}: NotFoundProps & { layout?: "centered" | "split" | "terminal" }) {
  const split = layout === "split";
  const terminal = layout === "terminal";
  return (
    <section
      {...props}
      className={`w-full min-w-0 overflow-hidden border border-border bg-background text-foreground ${className}`}
    >
      {terminal && (
        <div
          aria-hidden="true"
          className="flex items-center gap-2 border-b border-border bg-muted/40 px-6 py-4"
        >
          <span className="size-2 rounded-full bg-muted-foreground/40" />
          <span className="size-2 rounded-full bg-muted-foreground/40" />
          <span className="size-2 rounded-full bg-muted-foreground/40" />
          <span className="ml-3 font-mono text-xs text-muted-foreground">navigation / request</span>
        </div>
      )}
      <div className={split ? "grid sm:grid-cols-2" : "px-6 py-16 sm:px-12 sm:py-24"}>
        <div
          aria-hidden="true"
          className={
            split
              ? "flex min-h-64 items-center justify-center border-b border-border bg-muted/30 p-8 sm:border-r sm:border-b-0"
              : terminal
                ? "mb-10"
                : "mb-8 text-center"
          }
        >
          {terminal ? (
            <div className="space-y-3 font-mono text-sm">
              <p className="text-muted-foreground">$ find requested-page</p>
              <p className="text-emerald-700 dark:text-emerald-500">Error 404: resource not found</p>
              <p className="text-muted-foreground">→ Try a different destination.</p>
            </div>
          ) : (
            <span className="select-none font-mono text-[clamp(5rem,18cqw,10rem)] leading-none font-semibold tracking-tighter text-foreground/15">
              404<span className="text-emerald-700 dark:text-emerald-500">.</span>
            </span>
          )}
        </div>
        <div
          className={
            split
              ? "flex flex-col justify-center px-6 py-12 sm:px-10 sm:py-20"
              : terminal
                ? "max-w-lg"
                : "mx-auto max-w-lg text-center"
          }
        >
          <p className="mb-4 font-mono text-xs tracking-widest text-muted-foreground uppercase">
            404 / Page not found
          </p>
          <h2 className={"typography-section-title"}>{title}</h2>
          <p className={`mt-4 typography-body`}>{description}</p>
          <div
            className={`mt-8 flex flex-wrap gap-3 ${!split && !terminal ? "justify-center" : ""}`}
          >
            <Button href={homeHref}>
              {homeLabel}
              <span aria-hidden="true">↗</span>
            </Button>
            {secondaryHref && (
              <Button href={secondaryHref} variant="ghost">
                {secondaryLabel}
              </Button>
            )}
          </div>
        </div>
      </div>
    </section>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});
